mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def tokget():
    global tok
    while True:
        try:
            tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    global tok
    if not tok: tokget()
    for i in range(200):
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30)
            return json.load(r)
        except urllib.error.HTTPError as e:
            if e.code==401: tokget()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404: return None
            else: notes.append((p,e.code)); time.sleep(0.5)
        except Exception as e: notes.append((p,str(e))); time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: notes.append(("diffdup",o,seen[o["id"]]))
        else: seen[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0;naive=0;statuses=set()
for o in seen.values():
    statuses.add(o["status"])
    s=o["placed_at"].replace("Z","+00:00");t=datetime.fromisoformat(s)
    if t.tzinfo is None: naive+=1;t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if o["status"]!="shipped" or not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    C=cust[c]
    if C is None: notes.append(("missingcust",o));continue
    v=(o["amount_cents"]*(100-C["discount_pct"])*2+100)//200
    reg[C["region"]]+=v;n+=1
json.dump({"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(pages,d["total_pages"],len(seen),naive,statuses,[x for x in notes if x[0] in("diffdup","missingcust")][:5],len(notes))
print(open("/workspace/result.json").read())
EOF
python3 -I /tmp/work/r.py

